// Optimized version notes:
//
// 1. We still respect the k–outer, i–middle, j–inner loop structure,
//    but we express it using Noarr traversers and for_dims.
// 2. For each fixed (k, i) we load path[i][k] only once into a local
//    variable `pik` and reuse it across all j in that row. This reduces
//    the number of Noarr indexing operations and memory loads compared
//    to the baseline, where path[i][k] was accessed for every (i, j).
// 3. To preserve the exact semantics of the original in‑place algorithm
//    (even if weights were negative), we track when j == k and update
//    `pik` after path[i][k] is potentially changed. This mirrors the
//    fact that, in the original code, later iterations (j > k) see the
//    updated value of path[i][k].
// 4. Access pattern for the main matrix is still row‑major:
//    for a fixed i we traverse j in the innermost loop, which keeps
//    writes to path[i][j] cache‑friendly.
//
[[gnu::flatten, gnu::noinline]]
void kernel_floyd_warshall(std::size_t n, auto path) {
	using namespace noarr;

	// A dummy 1D structure used only to traverse k in [0, n)
	auto k_struct = noarr::scalar<char>() ^ k_vec ^ noarr::set_length<'k'>(n);

#pragma scop
	// Outer loop over k
	traverser(k_struct).for_each([&](auto sk) {
		const std::size_t k = get_index<'k'>(sk);

		// Middle loop over i: we fix 'i' and then traverse all 'j'
		// for that row. This ensures 'j' is the innermost dimension.
		traverser(path).template for_dims<'i'>([&](auto t_i) {
			// t_i has 'i' fixed, only 'j' remains unfixed
			auto si = t_i.state();
			const std::size_t i = get_index<'i'>(si);

			// Load path[i][k] once per (k, i) and reuse it across all j.
			// This substantially reduces Noarr indexing and memory traffic
			// for the column access.
			num_t pik = path[noarr::idx<'i', 'j'>(i, k)];

			// Inner loop over j for this fixed (k, i)
			t_i.for_each([&](auto sij) {
				const std::size_t j = get_index<'j'>(sij);

				// Current distance path[i][j]
				num_t &pij = path[sij];

				// Distance via intermediate k: path[i][k] + path[k][j]
				// - path[i][k] is `pik` (kept in a register where possible)
				// - path[k][j] is accessed row‑wise (good locality for row k)
				const num_t pkj = path[noarr::idx<'i', 'j'>(k, j)];
				const num_t via_k = pik + pkj;

				// Branchless min: same as the original ternary
				pij = (pij < via_k) ? pij : via_k;

				// To match the original in‑place algorithm exactly:
				// when j == k we have just potentially updated path[i][k]
				// (since pij aliases that element). Subsequent iterations
				// with j > k must see this new value, so we refresh `pik`.
				if (j == k)
					pik = pij;
			});
		});
	});
#pragma endscop
}

