//   * uses Noarr's ability to traverse multiple structures at once,
//   * exposes row-major access explicitly (i outer, j inner),
//   * avoids rebuilding index states for path[i][k] and path[k][j] on every (i,j)
//     iteration, while still re-reading path[i][k] each time so the semantics are
//     identical to the original triple loop (even if path[i][k] changes when j == k).
//
[[gnu::flatten, gnu::noinline]]
void kernel_floyd_warshall(std::size_t n, auto path) {
	using namespace noarr;

	// A dummy 1D structure used only to traverse k in [0, n)
	auto k_struct = noarr::scalar<char>() ^ k_vec ^ noarr::set_length<'k'>(n);

#pragma scop
	// Outer loop over k = 0 .. n-1
	traverser(k_struct).for_each([&](auto sk) {
		const std::size_t k = get_index<'k'>(sk);

