				// sij has both 'i' and 'j':
				//   path[sij]      -> path[i][j]
				//   path_row_k[sij]-> path[k][j]   (i is ignored by path_row_k)
				const num_t pik = path[sik];          // path[i][k], possibly updated
				const num_t pkj = path_row_k[sij];    // path[k][j]
				num_t &pij = path[sij];               // path[i][j]

