//        col_k[i] = path[i][k]
//    This is done using Noarr traversers and views (no raw pointer arithmetic).
//
//    - This turns two strided access patterns in the large n×n matrix into
//      sequential accesses into small 1D arrays, greatly improving cache
//      behavior.
//    - During the n×n update step for a fixed k, we no longer read
//      path[i][k] or path[k][j] from the big matrix; we read them from
//      row_k / col_k instead. Each entry in the k-th row/column of the
//      matrix is loaded only once per k instead of O(n) times.
//    - The extra memory is 2·n elements (row_k and col_k), which is far
//      less than 50% of the original n×n storage.
//
// 3. All loops are still expressed in terms of Noarr traversers; element
//    accesses use bag[state] as required.
//
[[gnu::flatten, gnu::noinline]]
void kernel_floyd_warshall(std::size_t n, auto path) {
	using namespace noarr;

	// A dummy 1D structure used only to traverse k in [0, n)
	auto k_struct = noarr::scalar<char>() ^ k_vec ^ noarr::set_length<'k'>(n);

	// Temporary buffers for the k-th row and k-th column.
	// Allocated once and reused for all k.
	std::vector<num_t> row_k(n); // row_k[j]  ~ path[k][j]
	std::vector<num_t> col_k(n); // col_k[i]  ~ path[i][k]

#pragma scop
	// Outer loop: k = 0 .. n-1
	traverser(k_struct).for_each([&](auto sk) {
		const std::size_t k = get_index<'k'>(sk);

		// --------------------------------------------------------------------
		// 1) Preload k-th row: path[k][j] for all j
		//    We create a view that fixes 'i' = k, so the traverser iterates
		//    over the row in the fast 'j' dimension.
		// --------------------------------------------------------------------
		traverser(path).order(noarr::fix<'i'>(k)).for_each([&](auto sj) {
			const std::size_t j = get_index<'j'>(sj);
			row_k[j] = path[sj];
		});

		// --------------------------------------------------------------------
		// 2) Preload k-th column: path[i][k] for all i
		//    We create a view that fixes 'j' = k, so the traverser iterates
		//    over the column in the 'i' dimension.
		// --------------------------------------------------------------------
		traverser(path).order(noarr::fix<'j'>(k)).for_each([&](auto si) {
			const std::size_t i = get_index<'i'>(si);
			col_k[i] = path[si];
		});

		// --------------------------------------------------------------------
		// 3) Main n×n update using the preloaded row/column
		//
		//    For each pair (i, j):
		//      via_k = col_k[i] + row_k[j]  ≡ path[i][k] + path[k][j]
		//      path[i][j] = min(path[i][j], via_k)
		//
		//    This preserves the original Floyd–Warshall semantics because:
		//      - row_k and col_k are snapshots of the matrix at the
		//        beginning of this k-iteration (i.e. distances using
		//        intermediate vertices < k).
		//      - During the k-iteration, updates to path[i][j] do not affect
		//        any other via_k computation for the same k.
		//      - Updates to path[i][k] or path[k][j] for j == k or i == k
		//        would be redundant (they cannot improve the distance since
		//        all edge weights are non-negative), so using the snapshot
		//        values from col_k / row_k is still correct.
		// --------------------------------------------------------------------
		traverser(path).for_each([&](auto sij) {
			auto [i, j] = get_indices<'i', 'j'>(sij);

			const num_t via_k = col_k[i] + row_k[j];
			num_t &pij = path[sij];

			if (via_k < pij)
				pij = via_k;
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	// build common length descriptor
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate data
	auto path = noarr::bag(noarr::scalar<num_t>() ^ tuning.path_layout ^ set_lengths);

	// initialize data
	init_array(path.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_floyd_warshall(n, path.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (for DCE / correctness checking)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, path.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
